      tar: tar,
      gzip: gzip,
      zip: zip,
      python: python,
      qjs: qjs,
      sqlite3: sqlite3,
      lua: lua,
      workingDirectory: _currentDir,
      sandboxHostPath: sandboxHostPath,
      httpClient: _httpClient,
      moduleLoader: moduleLoader,
      lazyModuleCache: _lazyModules,
