      final expanded = await expandShellWord(body, env, substitute);
      if (expanded.isErr) return Err(expanded.errorOrNull!);
      body = expanded.valueOrNull!.text;
    }
    redirects.add(
      Redirect(
        kind: redirect.kind,
        fd: redirect.fd,
        target: target,
        body: body,
      ),
    );
