    final resolved = _resolve(command);
    final eager = resolved.module;
    if (eager != null) return Ok(eager);
    final asset = switch (command) {
      'python' || 'python3' => 'python.wasm',
      'qjs' || 'js' => 'qjs.wasm',
      'sqlite3' => 'sqlite3.wasm',
      _ => 'lua.wasm',
