  int? _lastStageExitCode;

  io.File _hostFile(String sandboxPath) {
    final host = sandboxHostPath ?? '';
    final stripped = sandboxPath.startsWith('/')
        ? sandboxPath.substring(1)
        : sandboxPath;
    return io.File('$host/$stripped');
