SandboxHostRoot? _hostRoot;
bool _hostRootReady = false;

SandboxHostRoot? get _sandboxHostRoot {
  if (!_hostRootReady) {
    _hostRootReady = true;
    final host = sandboxHostPath;
    if (host != null && host.isNotEmpty) _hostRoot = SandboxHostRoot(host);
