    final cwdArgs = _rewriteRelativeArgs(command, args, cwd);
    final effectiveArgs = inputSource != null && command != 'rg'
        ? [...cwdArgs, inputSource]
        : cwdArgs;
    return _runStage(
      command: command,
      args: effectiveArgs,
      options: options,
      captureStdout: captureStdout,
      captureStderr: captureStderr,
