    String command,
    List<String> args,
    ShellExecOptions? options,
    String cwd,
    String? stdinText,
  ) async {
    if (!_availableCommands.contains(command)) {
      return _StageResult(
        stdout: const [],
        stderr: utf8.encode('$command: command not found\n'),
        exitCode: 127,
