      'ls' => _ls(ctx),
      'mkdir' => _mkdir(ctx),
      'rmdir' => _rmdir(ctx),
      'touch' => _touch(ctx),
      'cp' => _cp(ctx),
      'mv' => _mv(ctx),
      'rm' => _rm(ctx),
      'pwd' => _text('${ctx.cwd}\n'),
      'cd' => _cd(ctx),
      'grep' => _grep(ctx),
      'head' => _headTail(ctx, head: true),
      'tail' => _headTail(ctx, head: false),
      'wc' => _wc(ctx),
      'sort' => _sort(ctx),
      'tr' => _tr(ctx),
